const AGENCY_NAME = "TopTravels & Co.";
const TIME_ZONE = "Africa/Lagos";

function normalizeKey(key) {
  return key.toLowerCase().replace(/[\s_-]/g, "");
}

function getValue(data, possibleNames) {
  const entry = Object.entries(data).find(([key]) =>
    possibleNames.map(normalizeKey).includes(normalizeKey(key))
  );
  return entry ? entry[1] : "";
}

function dateKey(value) {
  if (!value) return "";

  const text = String(value).trim();

  // Handles dates already formatted as YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}/.test(text)) {
    return text.slice(0, 10);
  }

  // Handles other recognizable date formats
  const date = new Date(value);
  if (isNaN(date.getTime())) return "";

  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "UTC",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(date);
}

function addDays(dateString, days) {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

const today = new Intl.DateTimeFormat("en-CA", {
  timeZone: TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(new Date());

