return $input.all().map(item => {
  const data = item.json;

  const customerName = String(
    getValue(data, ["CustomerName", "Customer Name", "Name"])
  ).trim();

  const email = getValue(data, ["EmailAddress", "Email Address", "Email"]);
  const departureDate = dateKey(
    getValue(data, ["DepartureDate", "Departure Date"])
  );
  const returnDate = dateKey(
    getValue(data, ["ReturnDate", "Return Date"])
  );

  const preStatus = String(
    getValue(data, ["PreTripStatus", "Pre Trip Status"])
  ).trim().toLowerCase();

  const postStatus = String(
    getValue(data, ["PostTripStatus", "Post Trip Status"])
  ).trim().toLowerCase();

  let messageType = "None";
  let tripDate = "";
  let subject = "";
  let generatedMessage = "";
  let generatedMessageHtml = "";

  if (
    departureDate &&
    departureDate === addDays(today, 3) &&
    preStatus !== "sent"
  ) {
    messageType = "Pre-trip";
    tripDate = departureDate;
  } else if (
    returnDate &&
    returnDate === addDays(today, -1) &&
    postStatus !== "sent"
  ) {
    messageType = "Post-trip";
    tripDate = returnDate;
  }

  if (messageType !== "None") {
    const message = emailTemplate(customerName || "Traveler", messageType, tripDate);
    subject = message.subject;
    generatedMessage = message.plainText;
    generatedMessageHtml = message.html;
  }

  return {
    json: {
      ...data,
      CustomerName: customerName,
      EmailAddress: email,
      MessageType: messageType,
      TripDate: tripDate,
      EmailSubject: subject,
      GeneratedMessage: generatedMessage,
      GeneratedMessageHtml: generatedMessageHtml
    }
  };
});

function normalizeKey(value) {
  return String(value ?? "").trim().toLowerCase();
}

// Collect every ReminderKey already stored in the log
const loggedKeys = new Set(
  $input.all()
    .map(item => normalizeKey(item.json.ReminderKey))
    .filter(Boolean)
);

// Retrieve all reminders currently due
const remindersToCheck = $('Edit Fields').all();

// Keep only reminders whose keys are NOT already logged
return remindersToCheck.filter(item => {
  const currentKey = normalizeKey(item.json.ReminderKey);

  return currentKey && !loggedKeys.has(currentKey);
});
